files.content:
body {
  font-family: Arial, sans-serif;
  background: #fdf3e7;
  color: #333;
  text-align: center;
  margin: 0;
  padding: 20px;
}

.photo {
  font-size: 80px;
  background: #ffcf8a;
  border: 5px solid white;
  border-radius: 50%;
  width: 140px;
  height: 140px;
  line-height: 140px;
  margin: 20px auto;
}

h1 {
  color: #e8613c;
}

section {
  background: white;
  border-radius: 12px;
  padding: 20px;
  margin: 20px auto;
  max-width: 400px;
}

ul {
  text-align: left;
}

li {
  margin: 10px 0;
}

footer {
  color: #999;
  font-size: 14px;
}

